// CRITERES-V1 criterion 4: the tap is right on at least 2 000 random points of the whole village at
// tier 12, away from a 8 px band around any edge, against the truth at full resolution (the sprite's
// alpha, the depth order of profondeur.ts). The full-resolution alpha is __tests__/data/iso-tap-alpha.json
// (jest cannot decode WebP), regenerated by __tests__/data/iso-tap-alpha.py.

import assert from "node:assert/strict";
import type { Rect } from "@/components/village/iso/carteDemo";
import { etatCarte, spriteDe, stadeReel } from "@/components/village/iso/carteDemo";
import { emplacements } from "@/components/village/iso/isoLayout";
import { nomImage } from "@/components/village/iso/isoSpec";
import { ordreProfondeur } from "@/components/village/iso/profondeur";
import { batimentAuPoint, type Cible, cibles } from "@/components/village/iso/tapBatiment";
import type { BuildingCode } from "@/db/schema";
import alphas from "./data/iso-tap-alpha.json";

const POINTS = 2000;
// The band is 8 px of SPRITE (isoSpec S = 384 px a cell, 48 dp a cell: 8 px is 1 dp), harsher than
// 8 screen px at any zoom. The mask's error is up to 7 sprite px at an edge (blocks of 8), so the
// band leaves no margin to spare: a point farther than 8 px from every edge is always right.
const BANDE = 8;

// mulberry32: a fixed seed, so the draw and the verdict are the same on every machine.
function graine(depart: number) {
  let a = depart;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

type Plein = { w: number; h: number; bits: Uint8Array };
const decode = (s: { w: number; h: number; runs: number[] }): Plein => {
  const bits = new Uint8Array(s.w * s.h);
  let i = 0;
  s.runs.forEach((n, k) => {
    if (k % 2 === 1) bits.fill(1, i, i + n);
    i += n;
  });
  return { w: s.w, h: s.h, bits };
};
const alpha = (p: Plein, u: number, v: number) =>
  u >= 0 && v >= 0 && u < p.w && v < p.h && p.bits[v * p.w + u] === 1;

/** Whether both opaque and clear pixels lie within BANDE px of (u, v). */
function bord(plein: Plein, u: number, v: number): boolean {
  let sur = 0;
  let hors = 0;
  for (let dv = -BANDE; dv <= BANDE; dv++)
    for (let du = -BANDE; du <= BANDE; du++) alpha(plein, u + du, v + dv) ? sur++ : hors++;
  return sur > 0 && hors > 0;
}

type Vrai = { code: BuildingCode; rect: Rect; plein: Plein };

/** The building truly under `p` at full resolution, and whether an edge lies within BANDE px. */
function verite(p: readonly [number, number], vrais: readonly Vrai[]) {
  let vrai: BuildingCode | null = null;
  let pres = false;
  for (const { code, rect, plein } of vrais) {
    const u = Math.floor(((p[0] - rect.x) / rect.w) * plein.w);
    const v = Math.floor(((p[1] - rect.y) / rect.h) * plein.h);
    if (u < -BANDE || v < -BANDE || u >= plein.w + BANDE || v >= plein.h + BANDE) continue;
    if (bord(plein, u, v)) pres = true;
    if (alpha(plein, u, v)) vrai = code;
  }
  return { vrai, pres };
}

/** Draws points until POINTS lie outside the band, and counts the taps that match the truth. */
function mesurer(
  tirer: (h: () => number) => [number, number],
  hasard: () => number,
  vrais: readonly Vrai[],
  liste: readonly Cible[],
) {
  let bons = 0;
  let ecartes = 0;
  let surBatiment = 0;
  const erreurs: string[] = [];
  while (bons + erreurs.length < POINTS) {
    const p = tirer(hasard);
    const { vrai, pres } = verite(p, vrais);
    ecartes += pres ? 1 : 0;
    if (pres) continue;
    surBatiment += vrai ? 1 : 0;
    const touche = batimentAuPoint(p, liste);
    if (touche === vrai) bons++;
    else erreurs.push(`${p.map((c) => c.toFixed(1))}: ${vrai} vs ${touche}`);
  }
  return { bons, ecartes, surBatiment, erreurs };
}

describe("tap precision at tier 12 (criterion 4)", () => {
  it("is right on 2 000 random points, outside the 8 px band around an edge", () => {
    const { montres } = etatCarte(12, true);
    const stade = (c: BuildingCode) => stadeReel(c, "grand");
    const liste = cibles(montres, stade);
    expect(liste.length).toBeGreaterThanOrEqual(20);
    // Every shown building has a mask: none escapes the draw.
    expect(liste.length).toBe(montres.length);

    // Truth, back to front by profondeur.ts on the footprints alone.
    const ordre = ordreProfondeur(
      Object.fromEntries(liste.map((c) => [c.code, emplacements[c.code]])) as Record<
        BuildingCode,
        (typeof emplacements)[BuildingCode]
      >,
    );
    const vrais = ordre.flatMap((code) => {
      const cible = liste.find((c) => c.code === code);
      const s = spriteDe(code, stade(code));
      const cle = nomImage(code, stade(code), "nuit");
      const plein = (alphas as Record<string, { w: number; h: number; runs: number[] }>)[cle];
      assert(cible && s && plein, `no full-resolution alpha for ${code}`);
      assert.deepEqual([plein.w, plein.h], [...s.size]);
      return [{ code, rect: cible.rect, plein: decode(plein) }];
    });

    const [x0, x1] = [
      Math.min(...vrais.map((v) => v.rect.x)),
      Math.max(...vrais.map((v) => v.rect.x + v.rect.w)),
    ];
    const [y0, y1] = [
      Math.min(...vrais.map((v) => v.rect.y)),
      Math.max(...vrais.map((v) => v.rect.y + v.rect.h)),
    ];
    // Draw 1: the whole bounding box of the village. Draw 2: inside a random sprite's own box.
    const tirages: Record<string, (h: () => number) => [number, number]> = {
      "bounding box": (h) => [x0 + h() * (x1 - x0), y0 + h() * (y1 - y0)],
      "sprite boxes": (h) => {
        const choisi = vrais[Math.floor(h() * vrais.length)];
        assert(choisi);
        const { rect } = choisi;
        return [rect.x + h() * rect.w, rect.y + h() * rect.h];
      },
    };
    for (const [nom, tirer] of Object.entries(tirages)) {
      const { bons, ecartes, surBatiment, erreurs } = mesurer(
        tirer,
        graine(nom === "bounding box" ? 20261029 : 20261030),
        vrais,
        liste,
      );
      console.info(
        `tap precision (${nom}): ${bons}/${POINTS} right (${surBatiment} on a building), ${ecartes} more points dropped for the band`,
      );
      expect(erreurs).toEqual([]);
      expect(bons).toBe(POINTS);
    }
  });
});
